using System.Text;
using BenchmarkDotNet.Attributes;
using Org.SbeTool.Sbe.Dll;
using SBESharp;
using Ref = RefSbe.Car;
using Sbe = SBESharp.TestSchemas.Car;

namespace SBESharp.Benchmarks;

/// <summary>
/// Head-to-head encode/decode of the canonical SBE "Car" message:
/// SBESharp (source-generated) versus the Real Logic reference C# codec
/// (Org.SbeTool, generated by the official Java tool, vendored under Vendor/RefSbe).
/// Both sides use the identical schema, so the wire layout is byte-for-byte the same —
/// <see cref="Setup"/> asserts this before any measurement.
/// </summary>
[MemoryDiagnoser]
public class CarBenchmarks
{
	// Group dimension header (uint16 blockLength + uint16 numInGroup) and varData length prefix (uint32).
	private const int GroupHeaderSize = 4;
	private const int HeaderSize = 8;

	private const ulong SerialNumber = 1_234_567UL;
	private const ushort ModelYear = 2024;

	private readonly uint[] _someNumbers = [1, 2, 3, 4, 5];
	private readonly byte[] _vehicleCode = Encoding.ASCII.GetBytes("ABCDEF");
	private readonly byte[] _manufacturer = Encoding.UTF8.GetBytes("Honda");
	private readonly byte[] _model = Encoding.UTF8.GetBytes("Civic");
	private readonly byte[] _activationCode = Encoding.UTF8.GetBytes("ACT1234567");

	private readonly byte[] _encodeBuffer = new byte[256];
	private readonly byte[] _decodeBuffer = new byte[256];
	private readonly byte[] _scratch = new byte[64];

	private readonly Ref.Car _refCar = new();
	private readonly Ref.MessageHeader _refHeader = new();
	private DirectBuffer _refEncodeDb = null!;
	private DirectBuffer _refDecodeDb = null!;

	[GlobalSetup]
	public void Setup()
	{
		_refEncodeDb = new DirectBuffer(_encodeBuffer);

		// Pre-encode the decode buffer with the reference codec: it writes the SBE header plus body.
		// SBESharp skips the header and reads the identical body, so one buffer feeds both decoders.
		_refDecodeDb = new DirectBuffer(_decodeBuffer);
		int refLen = EncodeRef();

		// Fairness gate: both encoders must produce identical body bytes (everything after the 8-byte header).
		byte[] sbeBuf = new byte[256];
		int sbeLen = EncodeSbe(sbeBuf);
		if (sbeLen != refLen)
		{
			throw new InvalidOperationException($"Encoded lengths differ: SBESharp={sbeLen}, RealLogic={refLen}.");
		}

		for (int i = HeaderSize; i < sbeLen; i++)
		{
			if (sbeBuf[i] != _decodeBuffer[i])
			{
				throw new InvalidOperationException($"Wire bytes differ at offset {i}: the comparison is not apples-to-apples.");
			}
		}
	}

	[GlobalCleanup]
	public void Cleanup()
	{
		_refEncodeDb.Dispose();
		_refDecodeDb.Dispose();
	}

	[Benchmark(Description = "SBESharp encode")]
	public int SbeSharpEncode() => EncodeSbe(_encodeBuffer);

	[Benchmark(Description = "Real Logic encode")]
	public int RealLogicEncode() => EncodeRefInto(_refEncodeDb);

	[Benchmark(Description = "SBESharp decode")]
	public long SbeSharpDecode()
	{
		Sbe.Car msg = SbeSerializer.Deserialize<Sbe.Car>(_decodeBuffer);
		long acc = (long)msg.SerialNumber + msg.ModelYear + (long)msg.Available + (long)msg.Code + (long)msg.Extras;

		ReadOnlySpan<uint> numbers = msg.SomeNumbers;
		for (int i = 0; i < numbers.Length; i++)
		{
			acc += numbers[i];
		}

		acc += msg.VehicleCode.Length;
		acc += msg.Manufacturer.Length + msg.Model.Length + msg.ActivationCode.Length;
		return acc;
	}

	[Benchmark(Description = "Real Logic decode")]
	public long RealLogicDecode()
	{
		_refHeader.Wrap(_refDecodeDb, 0, Ref.Car.SchemaVersion);
		int blockLength = _refHeader.BlockLength;
		int version = _refHeader.Version;

		_refCar.WrapForDecode(_refDecodeDb, HeaderSize, blockLength, version);
		long acc = (long)_refCar.SerialNumber + _refCar.ModelYear + (long)_refCar.Available + (long)_refCar.Code + (long)_refCar.Extras;

		for (int i = 0; i < Ref.Car.SomeNumbersLength; i++)
		{
			acc += _refCar.GetSomeNumbers(i);
		}

		acc += Ref.Car.VehicleCodeLength;

		// Groups must be consumed (in wire order) before variable-length data.
		Ref.Car.FuelFiguresGroup fuel = _refCar.FuelFigures;
		while (fuel.HasNext)
		{
			fuel.Next();
		}

		Ref.Car.PerformanceFiguresGroup perf = _refCar.PerformanceFigures;
		while (perf.HasNext)
		{
			perf.Next();
		}

		acc += _refCar.GetManufacturer(_scratch);
		acc += _refCar.GetModel(_scratch);
		acc += _refCar.GetActivationCode(_scratch);
		return acc;
	}

	private int EncodeSbe(byte[] buffer)
	{
		Sbe.CarEncoder.Encode(buffer, offset: HeaderSize)
			.SetSerialNumber(SerialNumber)
			.SetModelYear(ModelYear)
			.SetAvailable(Sbe.BooleanType.T)
			.SetCode(Sbe.Model.A)
			.SetSomeNumbers(_someNumbers)
			.SetVehicleCode(_vehicleCode)
			.SetExtras(Sbe.OptionalExtras.sunRoof | Sbe.OptionalExtras.cruiseControl);

		int fuelOffset = HeaderSize + Sbe.Car.SbeBlockLength;
		Sbe.CarFuelFiguresGroupEncoder.Open(buffer, fuelOffset, count: 0);

		int perfOffset = fuelOffset + GroupHeaderSize;
		Sbe.CarPerformanceFiguresGroupEncoder.Open(buffer, perfOffset, count: 0);

		int varOffset = perfOffset + GroupHeaderSize;
		varOffset += Sbe.CarEncoder.WriteManufacturer(buffer, varOffset, _manufacturer);
		varOffset += Sbe.CarEncoder.WriteModel(buffer, varOffset, _model);
		varOffset += Sbe.CarEncoder.WriteActivationCode(buffer, varOffset, _activationCode);
		return varOffset;
	}

	private int EncodeRef() => EncodeRefInto(_refDecodeDb);

	private int EncodeRefInto(DirectBuffer buffer)
	{
		_refHeader.Wrap(buffer, 0, Ref.Car.SchemaVersion);
		_refHeader.BlockLength = Ref.Car.BlockLength;
		_refHeader.TemplateId = Ref.Car.TemplateId;
		_refHeader.SchemaId = Ref.Car.SchemaId;
		_refHeader.Version = Ref.Car.SchemaVersion;

		_refCar.WrapForEncode(buffer, HeaderSize);
		_refCar.SerialNumber = SerialNumber;
		_refCar.ModelYear = ModelYear;
		_refCar.Available = Ref.BooleanType.T;
		_refCar.Code = Ref.Model.A;

		for (int i = 0; i < _someNumbers.Length; i++)
		{
			_refCar.SetSomeNumbers(i, _someNumbers[i]);
		}

		_refCar.SetVehicleCode((ReadOnlySpan<byte>)_vehicleCode);
		_refCar.Extras = Ref.OptionalExtras.SunRoof | Ref.OptionalExtras.CruiseControl;

		_refCar.FuelFiguresCount(0);
		_refCar.PerformanceFiguresCount(0);
		_refCar.SetManufacturer((ReadOnlySpan<byte>)_manufacturer);
		_refCar.SetModel((ReadOnlySpan<byte>)_model);
		_refCar.SetActivationCode((ReadOnlySpan<byte>)_activationCode);
		return _refCar.Limit;
	}
}
